'use strict'

const { test } = require('node:test')
const assert = require('node:assert/strict')
const { ContentType } = require('../lib/content-type')

test('ContentType.cache exists and is an LRU', async (t) => {
  assert.ok(ContentType.cache, 'cache getter must exist')
  assert.equal(typeof ContentType.cache.get, 'function', 'cache must have get()')
  assert.equal(typeof ContentType.cache.set, 'function', 'cache must have set()')
})

test('ContentType.from returns cached instance', async (t) => {
  const a = ContentType.from('text/plain')
  const b = ContentType.from('text/plain')
  assert.equal(a, b, 'same header must return same object')
})

