'use strict'

const { test } = require('node:test')
const assert = require('node:assert/strict')
const Fastify = require('../fastify')

test('max param length returns 414, not 413', async (t) => {
  const fastify = Fastify({ maxParamLength: 5 })
  fastify.get('/:id', async (req) => ({ id: req.params.id }))
  const res = await fastify.inject({ method: 'GET', url: '/' + 'x'.repeat(20) })
  assert.equal(res.statusCode, 414)
  const body = JSON.parse(res.body)
  assert.equal(body.code, 'FST_ERR_MAX_PARAM_LENGTH')
})
